BROWSER="import{renderOriginal,renderGrowingCaps,renderWhole,renderTargetOnly,targetMask,targetCoverageResidual,measureBrowserFrame,browserMetrics}from'/render.mjs';const C=await(await fetch('/config.json')).json(),F=await(await fetch('/fixture.json')).json(),S=F.u8a29.strokes,$=s=>document.querySelector(s);let pen=8,p=0,serial=0,errors=[];function status(mode,extra={}){$('#status').textContent=JSON.stringify({mode,pen,requestedGlobal:p,report:browserMetrics(),errors,...extra})}function paint(){try{$('#reference').innerHTML=renderOriginal(S,pen,p,'reference');$('#candidate').innerHTML=renderGrowingCaps(S,pen,p,'candidate');$('#progress').value=p*100;$('#percent').textContent=(p*100).toFixed(10)+'%';status('main')}catch(e){$('#candidate').innerHTML='';errors.push(String(e));status('invalid-hidden')}}function record(svg,label,width,reference=null,report=null){const d=document.createElement('section');d.className='sample';d.innerHTML='<h3>'+label+'</h3>'+(reference===null?'<p>후보만 표시/reference숨김</p>':'<div class=\"sample-ref\">'+reference+'</div>')+'<div class=\"sample-new\">'+svg+'</div>';for(const s of d.querySelectorAll('svg')){s.style.width=width+'px';s.style.height=width+'px'}d.dataset.report=JSON.stringify(report);$('#samples').appendChild(d);d.scrollIntoView({block:'start'});return d}function chosen(){return Number($('#target').value)}function targetSample(v,label='local'){pen=chosen();p=v;$('#pen').value=pen;$('#local').value=v;paint();const svg=renderTargetOnly(pen,v,'target-'+serial++);record(svg,'Q'+pen+'m1 target-only '+label+' '+v,520,null,browserMetrics());status('target-only',{requestedLocal:v})}for(const v of C.localSamples){const b=document.createElement('button');b.textContent='target local '+v;b.onclick=()=>targetSample(v);$('#locals').appendChild(b)}for(const v of C.earlyLocals){const b=document.createElement('button');b.textContent='초기연결 local '+v;b.onclick=()=>targetSample(v,'초기위험');$('#early').appendChild(b)}$('#target').onchange=()=>{pen=chosen();p=0;$('#pen').value=pen;paint()};$('#pen').onchange=e=>{pen=Number(e.target.value);p=0;paint()};$('#progress').oninput=e=>{p=Number(e.target.value)/100;paint()};$('#local').onchange=e=>targetSample(Number(e.target.value));$('#rho').onclick=()=>{const t=chosen(),frame=measureBrowserFrame(targetMask(t),.5);for(const e of[-1e-10,0,1e-10])targetSample(7/frame.L+e,'rho±1e-10')};$('#coverage').onclick=()=>{const t=chosen();record(targetCoverageResidual(targetMask(t),'coverage-'+serial++),'Q'+t+' P-minus-original-fullround · marker없음',520);$('#status').textContent=JSON.stringify({mode:'coverage',target:t,report:null,errors})};$('#whole').onclick=()=>{$('#reference').innerHTML=renderOriginal(S,11,1,'reference-whole');$('#candidate').innerHTML=renderWhole(S,'whole-'+serial++);status('whole',{requestedGlobal:1,mainGlobal:p})};$('#coarse').onclick=()=>{const compact=$('#compact').checked,size=compact?150:Number($('#size').value);$('#samples').innerHTML='';$('#samples').className=compact?'compact':'';for(const v of C.coarseSamples){const svg=renderGrowingCaps(S,pen,v,'coarse-'+serial++);record(svg,'pen'+pen+' global '+v,size,compact?null:renderOriginal(S,pen,v,'coarse-reference-'+serial),browserMetrics())}$('#samples').scrollIntoView({block:'start'});status('coarse-last-sample',{requestedGlobal:1,mainGlobal:p,sampleCount:9})};$('#fine').onclick=()=>{const current=pen,compact=$('#compact').checked,size=compact?150:Number($('#size').value);$('#samples').innerHTML='';$('#samples').className=compact?'compact':'';for(const v of[.9999,.99999999,1]){const svg=renderGrowingCaps(S,current,v,'fine-'+serial++);record(svg,'pen'+current+' global '+v,size,compact?null:renderOriginal(S,current,v,'fine-reference-'+serial),browserMetrics())}$('#samples').scrollIntoView({block:'start'});status('fine-last-sample',{requestedGlobal:1,mainGlobal:p,sampleCount:3,currentPen:current})};$('#clear').onclick=()=>{$('#samples').innerHTML='';$('#samples').className=''};$('#play').onclick=()=>{pen=chosen();$('#pen').value=pen;const start=performance.now();function tick(now){p=Math.min(1,(now-start)/8000);paint();if(p<1)requestAnimationFrame(tick);else $('#status').dataset.natural='complete'}requestAnimationFrame(tick)};window.koReports=()=>({current:JSON.parse($('#status').textContent),samples:[...document.querySelectorAll('#samples .sample')].map(d=>JSON.parse(d.dataset.report))});paint();"
def sha(b):return hashlib.sha256(b).hexdigest()
def guards():
    v=json.loads((HERE/'validation.json').read_text(encoding='utf-8'))
    for path,pin in CONFIG['inputSHA256'].items():assert sha((ROOT/path).read_bytes())==pin,'fixed input changed: '+path
    for name,pin in v['ownSHA256'].items():assert sha((HERE/name).read_bytes())==pin,'experiment changed: '+name
    b=(ROOT/CONFIG['sourceFixture']).read_bytes();assert sha(b)==CONFIG['fixtureSHA256'],'fixture changed'
    return b
def selection(path,query):
    q=parse_qs(query,keep_blank_values=True,strict_parsing=True)if query else{}
    assert not q,'query unsupported'
    assert path in('/','/progressive','/render.mjs','/browser.js','/fixture.json','/config.json'),'route unsupported'
    return path
